using System.Drawing;using System.Linq;using System.Windows.Forms;using AshkanPharmacy.Core;
namespace AshkanPharmacy.Forms{public partial class InventoryForm:Form{public InventoryForm(){InitializeComponent();BackColor=Color.FromArgb(233,248,246);AutoScroll=true;PageChrome.Header(this,Localization.Persian?"مرکز کنترل موجودی":"Inventory Control Center",Localization.Persian?"Batch، FEFO، انقضا و سلامت موجودی":"Batch, FEFO, expiry and inventory health",Color.FromArgb(20,145,120),Color.FromArgb(41,102,124));var h=new Label{Text=Localization.Persian?"کنترل موجودی، بچ و تاریخ انقضا":"Stock, Batch & Expiry Control",Left=25,Top=155,Width=650,Font=Theme.Font(17,FontStyle.Bold),ForeColor=Theme.Navy};var g=new DataGridView{Left=25,Top=220,Width=950,Height=460,ReadOnly=true,AllowUserToAddRows=false};Theme.StyleGrid(g);g.DataSource=AppStore.Medicines.Select(m=>new{Name=Localization.Persian?m.NameFa:m.NameEn,m.Stock,Minimum=m.MinStock,m.Batch,m.Expiry,Status=m.Stock<=m.MinStock?(Localization.Persian?"سفارش مجدد":"Reorder"):(Localization.Persian?"مناسب":"Healthy")}).ToList();Controls.AddRange(new Control[]{h,g});}}}
